package com.cvns.controller;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.cvns.dtos.ResponseDtos.ApiResponse;import com.cvns.service.DashboardService;import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/dashboard") @RequiredArgsConstructor public class DashboardController{private final DashboardService s;@GetMapping @PreAuthorize("hasRole('PARENT')")public ResponseEntity<?> dashboard(){return ResponseEntity.ok(ApiResponse.success("Dashboard",s.dashboard()));}}
